# owner: platform
"""Contact sheet rows for substitute teachers."""

from rosterkit.errors import ProjectError


def _sort_key(student):
    return student.display_name.lower()


def _require_email(student):
    if not student.email:
        raise ProjectError(
            f"no email for {student.display_name}"
        )


def _widths(students):
    name = max(len(item.display_name) for item in students)
    sect = max(len(item.section) for item in students)
    return name, sect


def _format_row(student, widths):
    name, sect = widths
    return (
        f"{student.display_name:<{name}}  "
        f"{student.section:<{sect}}  {student.email}"
    )


# ---
def contact_rows(students):
    if not students:
        raise ProjectError("no students")
    ordered = sorted(students, key=_sort_key)
    for item in ordered:
        _require_email(item)
    widths = _widths(ordered)
    return [_format_row(item, widths) for item in ordered]

